        NOISE_GLSL, HALO_GLSL, 'varying vec3 vW;',
        'float fl(float u){ u = clamp(u, 0.0, 1.0); return uConvex > 0.5 ? 1.0 - pow(u, uP) : pow(1.0 - u, uP); }',
