                  ctx.strokeStyle = 'rgba(253,186,116,0.9)';
                  ctx.beginPath();
                  ctx.moveTo(ax - alen, couplingY);
                  ctx.lineTo(ax + alen, couplingY);
                  ctx.stroke();
                  ctx.fillStyle = 'rgba(253,186,116,0.95)';
